import yaml

# Read existing file
with open("/home/ubuntu/.agent-ml-research-idea_gen_0509_4/projects/trace-verdict-study/artifacts/review_issues.yaml", "r") as f:
    content = f.read()

# Parse (it uses list format with - id:)
issues = yaml.safe_load(content)

# Build lookup by id
lookup = {item['id']: item for item in issues}

# --- Update R13 mentions for active issues ---

# R1-N1: near-tautological (in_progress)
if 'R1-N1' in lookup:
    lookup['R1-N1']['last_seen_round'] = 13
    lookup['R1-N1']['mentions'].append({
        'round': 13, 'reviewers': [1, 2],
        'note': "RECURRING。R2-N1 Must-Fix (near-tautological: regex B5=99.33% vs SFT 99.83%, gap 0.50pp, exception事件在任务构造层面编码verdict) + R1 AGREE。'Less Is More' framing夸大反直觉性。建议reframe为'量化full trace为何有害'而非'exception为何优秀'"
    })

# R1-N3: decomposition (was resolved R12, reopen)
if 'R1-N3' in lookup:
    lookup['R1-N3']['status'] = 'in_progress'
    lookup['R1-N3']['last_seen_round'] = 13
    lookup['R1-N3']['mentions'].append({
        'round': 13, 'reviewers': [1, 2],
        'note': "RECURRING despite R12 wording changes。R1-N1 Must-Fix + R2 AGREE。label_only同时改变(a)gradient source(b)effective LR(c)training objective——三变量未隔离。CodeLlama/DeepSeek collapse至28.5%限制分解仅Qwen(2/4模型)。R12将C3降为preliminary analysis但confounders未解决"
    })
    lookup['R1-N3']['action_items'].append({
        'round': 13, 'action': '将24%/76%从点估计改为上界/下界区间；或设计中间条件隔离变量', 'assigned_to': 'paper_agent', 'status': 'open'
    })

# R9-N1: near-tautological (merge note)
if 'R9-N1' in lookup:
    lookup['R9-N1']['last_seen_round'] = 13
    lookup['R9-N1']['mentions'].append({
        'round': 13, 'reviewers': [1, 2],
        'note': "仍活跃。R13两位Reviewer独立AGREE此为#1问题。见R1-N1 Round 13"
    })

# R1-N2: test set duplicates
if 'R1-N2' in lookup:
    lookup['R1-N2']['last_seen_round'] = 13
    lookup['R1-N2']['mentions'].append({
        'round': 13, 'reviewers': [1, 2],
        'note': "R1-W3 Should-Fix (effective n≈607 CI被低估~1.4×) + R2 REBUT (0.00pp dedup delta)。Director: 点估计不受影响但CI宽度需调整"
    })

# R-BIB
if 'R-BIB' in lookup:
    lookup['R-BIB']['last_seen_round'] = 13
    lookup['R-BIB']['mentions'].append({
        'round': 13, 'reviewers': [2],
        'note': "R2引用验证：53 entries, 52 cited, 1 orphan(pornprasit2021jitline), 42 verified, 5 not found(likely recent), 6 author-encoding mismatches。无虚假引用"
    })

# R8-N2: single dataset
if 'R8-N2' in lookup:
    lookup['R8-N2']['last_seen_round'] = 13
    lookup['R8-N2']['mentions'].append({
        'round': 13, 'reviewers': [1, 2],
        'note': "RECURRING。DebugBench天花板(no_trace 96.71%, headroom 3.29pp) R2-W1 + R1 AGREE。cross-dataset validation区分力不足"
    })

# R8-N3: sequence length confound
if 'R8-N3' in lookup:
    lookup['R8-N3']['last_seen_round'] = 13
    lookup['R8-N3']['mentions'].append({
        'round': 13, 'reviewers': [1, 2],
        'note': "RECURRING。R1-W6 + R2-W2 互相AGREE。exception_only ~150 tokens vs full_trace >2048 tokens(>13×)未控制。controlled-length实验仍未补充"
    })

# R8-W1: task motivation
if 'R8-W1' in lookup:
    lookup['R8-W1']['last_seen_round'] = 13
    lookup['R8-W1']['mentions'].append({
        'round': 13, 'reviewers': [1, 2],
        'note': "RECURRING。R2-N2 Must-Fix → R1 REBUT(proxy task先例CRUXEval/NExT) → Director降为Should-Fix。分析研究定位成立但downstream连接仍薄弱"
    })

# R8-N4: single model ablation (resolved R12, add note)
if 'R8-N4' in lookup:
    lookup['R8-N4']['mentions'].append({
        'round': 13, 'reviewers': [1],
        'note': "R1-W2 Should-Fix: Table 2仍仅Qwen-7B。R12 C4降级为'observation/pattern'已部分缓解，但完整跨模型组件消融仍缺失。维持resolved(wording已改)但标注residual concern"
    })
    lookup['R8-N4']['last_seen_round'] = 13

# R10-W2: information density definition
if 'R10-W2' in lookup:
    lookup['R10-W2']['last_seen_round'] = 13
    lookup['R10-W2']['mentions'].append({
        'round': 13, 'reviewers': [1, 2],
        'note': "RECURRING。R1-W4 + R2 AGREE。§4有operationalization但(1)出现太晚(应在§2/3), (2)定义循环(verdict-relevant tokens由accuracy定义)"
    })

# R10-M1: formatting
if 'R10-M1' in lookup:
    lookup['R10-M1']['last_seen_round'] = 13
    lookup['R10-M1']['mentions'].append({
        'round': 13, 'reviewers': [1, 2],
        'note': "R1: Ethics GPU型号(RTX PRO 6000 Blackwell)可能缩小匿名范围。R2: orphan bib pornprasit2021jitline"
    })

# R11-W1: Abstract ~80%
if 'R11-W1' in lookup:
    lookup['R11-W1']['last_seen_round'] = 13
    lookup['R11-W1']['mentions'].append({
        'round': 13, 'reviewers': [1],
        'note': "R13 Abstract仍写'~80%'。基于Qwen-7B(81.76%)和DeepSeek(79.16%)近似合理，但应注明覆盖范围或改为跨模型范围"
    })

# R11-W2: Table 1 notation
if 'R11-W2' in lookup:
    lookup['R11-W2']['last_seen_round'] = 13
    lookup['R11-W2']['mentions'].append({
        'round': 13, 'reviewers': [1],
        'note': "Table 1已有†标注single-seed(no_trace)但其他single-seed条目标注仍需确认"
    })

# R9-W3: missing references
if 'R9-W3' in lookup:
    lookup['R9-W3']['last_seen_round'] = 13
    lookup['R9-W3']['mentions'].append({
        'round': 13, 'reviewers': [2],
        'note': "R2识别遗漏data selection方向：Paul et al.(2021) Deep Learning on a Data Diet, Sorscher et al.(2022) Beyond neural scaling laws"
    })

# R1-W3: 循环依赖 (resolved, add R13 note)
if 'R1-W3' in lookup:
    lookup['R1-W3']['last_seen_round'] = 13
    lookup['R1-W3']['mentions'].append({
        'round': 13, 'reviewers': [1, 2],
        'note': "R1-N3 Must-Fix → R2 REBUT(CodeLlama 100%排除Qwen-specific bias, 跨模型gap 0.50pp) → Director降为Should-Fix。维持resolved"
    })

# R10-W1: phase transition precision
if 'R10-W1' in lookup:
    lookup['R10-W1']['last_seen_round'] = 13
    lookup['R10-W1']['mentions'].append({
        'round': 13, 'reviewers': [1],
        'note': "R1 minor comment: 'phase transition'术语对N=4模型过精确。建议'sharp performance jump'"
    })

# --- Add new R13 issues ---

issues.append({
    'id': 'R13-N1',
    'summary': 'VOTA在所有4个模型上均不优于exception_only，方法贡献不成立',
    'category': 'method',
    'severity': 'critical',
    'status': 'open',
    'first_raised_round': 13,
    'last_seen_round': 13,
    'mentions': [{
        'round': 13, 'reviewers': [1, 2],
        'note': "R1-N2 Must-Fix + R2 AGREE。Table 1: Qwen-7B VOTA 99.05% vs exc 99.83%, Qwen-1.5B 99.54% vs 99.83%, CL-13B 98.74% vs 99.89%, DS 99.25% vs 99.39%——四模型全部VOTA≤exception_only。§2.3用完整一节介绍VOTA + Appendix C Algorithm 1但实验无增量"
    }],
    'action_items': [{
        'round': 13, 'action': '将论文重新定位为消融研究而非新方法提出；缩减VOTA介绍篇幅；或论证VOTA在更困难benchmark上的优势',
        'assigned_to': 'paper_agent', 'status': 'open'
    }],
    'resolution': '',
    'resolution_round': None
})

issues.append({
    'id': 'R13-W1',
    'summary': 'Conclusion过于简短(~4行)，缺方法论启示和未来方向',
    'category': 'writing',
    'severity': 'warning',
    'status': 'open',
    'first_raised_round': 13,
    'last_seen_round': 13,
    'mentions': [{
        'round': 13, 'reviewers': [1, 2],
        'note': "R2-W4 Should-Fix + R1 AGREE。§6仅重复核心发现，缺(1)方法论启示(2)局限性摘要(3)未来方向"
    }],
    'action_items': [{
        'round': 13, 'action': '扩充Conclusion至8-10行：增加方法论启示总结、关键局限提及、未来方向',
        'assigned_to': 'paper_agent', 'status': 'open'
    }],
    'resolution': '',
    'resolution_round': None
})

issues.append({
    'id': 'R13-W2',
    'summary': 'Format marker [No exception data in trace]是pipeline artifact，模糊learning vs pattern matching界限',
    'category': 'method',
    'severity': 'warning',
    'status': 'open',
    'first_raised_round': 13,
    'last_seen_round': 13,
    'mentions': [{
        'round': 13, 'reviewers': [1, 2],
        'note': "R2-W6 + R1 AGREE(部分)。marker在pass类中确定性出现=直接编码verdict。nomarker ablation显示~2pp marker贡献(错误率翻倍0.61%→2.52%)。nomarker条件下regex退化程度未报告——这是判断SFT真实增量的关键缺失对比"
    }],
    'action_items': [{
        'round': 13, 'action': '报告nomarker条件下regex baseline表现；更透明讨论marker角色',
        'assigned_to': 'paper_agent', 'status': 'open'
    }],
    'resolution': '',
    'resolution_round': None
})

# Update header
output = "# trace-verdict-study Review Issues Tracker\n"
output += "# Rounds 3-13: cumulative review sessions\n"
output += "# Round 13: Fresh review (2026-05-21)\n"
output += "# Updated 2026-05-21: Round 13 fresh review findings\n\n"

# Dump all issues
for issue in issues:
    output += yaml.dump([issue], default_flow_style=False, allow_unicode=True, sort_keys=False)
    output += "\n"

# Write to temp file for verification
with open("/tmp/review_issues_r13.yaml", "w") as f:
    f.write(output)

print(f"Generated {len(output)} chars, {len(issues)} issues")
print("First 200 chars:")
print(output[:200])
PYEOF

